  const m = /Z$/i.test(value) ? null : String(value).match(/^(\d{4})[-/]?(\d{1,2})?[-/]?(\d{0,2})[Tt\s]*(\d{1,2})?:?(\d{1,2})?:?(\d{1,2})?[.:]?(\d+)?$/);
  return m ? new Date(m[1], (m[2] || 1) - 1, m[3] || 1, m[4] || 0, m[5] || 0, m[6] || 0, (m[7] || '0').substring(0, 3)) : new Date(value);
};
const pad = (n) => String(n).padStart(2, '0');
const local = (value) => {
  const d = typeof value === 'number' ? new Date(value) : parse(value), s = d.getSeconds(), o = -d.getTimezoneOffset();
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + 'T' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(s) + '.' + pad(s) + s +
    (o < 0 ? '-' : '+') + pad(Math.floor(Math.abs(o) / 60)) + ':' + pad(Math.abs(o) % 60);
};
const form = (query) => Object.keys(query).filter((key) => query[key] !== undefined).map((key) => key + '=' +
  encodeURIComponent(query[key]).replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+')).join('&');
const types = JSON.parse(inputs.event_types || '[]');
const query = {showDeleted: 'false', singleEvents: inputs.singleEvents === 'true' ? 'true' : 'false'};
if (inputs.search) query.q = '"' + inputs.search + '"';
if (inputs.start_date) query.timeMin = local(inputs.start_date);
if (inputs.start_date && inputs.end_date) query.timeMax = local(inputs.end_date);
request.url = '/calendars/' + inputs.calendar_id + '/events?' + types.map((type) => 'eventTypes=' + type).concat(form(query)).join('&');
return request;

