google_calendar_remove_attendee.afterResponse:
const target = inputs.attendee_email.trim().toLowerCase();
const current = response.attendees || [];
const remaining = current.filter((attendee) => (attendee.email || '').trim().toLowerCase() !== target);
if (remaining.length === current.length) {
  return {removed: false, attendee_email: inputs.attendee_email, message: 'Attendee "' + inputs.attendee_email + '" was not on event "' + inputs.event_id + '"; nothing to remove.', event: response};
}
const headers = Object.assign({'x-goog-api-client': 'gdcl/8.0.2 gl-node/26.4.0'}, response.etag ? {'If-Match': response.etag} : {});
const event = call({method: 'PATCH', url: '/calendars/' + encodeURIComponent(inputs.calendar_id) + '/events/' + encodeURIComponent(inputs.event_id),
  query: {sendUpdates: inputs.send_updates || 'none'}, headers, body: {attendees: remaining}});
return {removed: true, attendee_email: inputs.attendee_email, event};

