google_calendar_list_calendars.afterResponse:
const calendars = response.items;
return {calendars: calendars.map((calendar) => ({id: calendar.id, summary: calendar.summary, description: calendar.description, location: calendar.location,
  timeZone: calendar.timeZone, accessRole: calendar.accessRole, primary: calendar.primary ?? false, selected: calendar.selected ?? false,
  backgroundColor: calendar.backgroundColor, foregroundColor: calendar.foregroundColor})), count: calendars.length};

google_calendar_list_settings.afterResponse:
const items = response.items ?? [], settings = {};
for (const item of items) settings[item.id] = item.value;
return {settings, items, count: items.length};
